#[non_exhaustive]
pub enum SectionBody {
    /// A uniform list, rendered as a TOON list with the response's per-cell truncation applied.
    Toon {
        /// Ordered, distinct field names.
        fields: Vec<String>,
        /// Rows, parallel to `fields`.
        rows: Vec<Vec<Value>>,
    },
    /// A single receipt or a small set of labelled scalars.
    Kv(Vec<KvItem>),
    /// One string value, rendered as `name: <value>` and escaped like any other TOON string (quoted when it has a
    /// newline, a colon, or looks like a number). Prose cannot start a line of its own, so it cannot forge a `help[]`
    /// line. It is not a way to insert a fragment of TOON.
    Text(String),
}

impl Section {
    /// A TOON list section. `returned_count` is `rows.len()`.
    #[must_use]
    pub fn toon(name: impl Into<String>, fields: Vec<String>, rows: Vec<Vec<Value>>) -> Self {
        Self::with(name, rows.len(), SectionBody::Toon { fields, rows })
    }

    /// A key-value section. `returned_count` is `items.len()`.
    #[must_use]
    pub fn kv(name: impl Into<String>, items: Vec<KvItem>) -> Self {
        Self::with(name, items.len(), SectionBody::Kv(items))
    }

    /// A text section: a single string value, rendered as `name: <escaped body>`. `returned_count` starts at 1 for
    /// non-empty text and 0 for empty; set it with [`returned_count`](Self::returned_count). A `totalCount` renders
    /// as for the other bodies, when [`total_count`](Self::total_count) exceeds that count.
    #[must_use]
    pub fn text(name: impl Into<String>, body: impl Into<String>) -> Self {
        let body = body.into();
        Self::with(name, usize::from(!body.is_empty()), SectionBody::Text(body))
    }

    fn with(name: impl Into<String>, returned_count: usize, body: SectionBody) -> Self {
        Self { name: name.into(), body, returned_count, total_count: None, truncated: false }
    }

    /// Record the pre-truncation count. `Some(n)` with `n` greater than the returned count renders `totalCount: n`.
    #[must_use]
    pub fn total_count(mut self, total: Option<usize>) -> Self {
        self.total_count = total;
        self
    }

    /// Record whether producing this section dropped anything.
    #[must_use]
    pub fn truncated(mut self, truncated: bool) -> Self {
        self.truncated = truncated;
        self
    }

    /// Declare how many items a `Text` body carries. Ignored for `Toon` and `Kv` bodies, whose count is derived.
    #[must_use]
    pub fn returned_count(mut self, n: usize) -> Self {
        if matches!(self.body, SectionBody::Text(_)) {
            self.returned_count = n;
        }
        self
    }

    /// The count rendering uses: `rows.len()` or `items.len()` for `Toon` and `Kv` bodies, the declared
    /// `returned_count` for `Text`. A hand-edited `returned_count` field cannot disagree with the body.
    #[must_use]
    pub fn count(&self) -> usize {
        match &self.body {
            SectionBody::Toon { rows, .. } => rows.len(),
            SectionBody::Kv(items) => items.len(),
            SectionBody::Text(_) => self.returned_count,
        }
    }

    /// The `totalCount` to render: `total_count` only when it exceeds [`count`](Self::count).
    pub(crate) fn shown_total(&self) -> Option<usize> {
        self.total_count.filter(|n| *n > self.count())
    }
}
//! Best-effort redaction of secrets from text before it reaches an agent.
//!
//! Two helpers, both pure and dependency-free:
//!
//! - [`redact_secrets`](crate::redact::redact_secrets) replaces values you already know are secret (a token you loaded, a password you were given).
//!   It is exact and reliable for those values.
//! - [`redact_url_userinfo`](crate::redact::redact_url_userinfo) removes the `user:password@` part of any URL in a text. It finds secrets you do not hold
//!   as a value, such as one inside an error from a library.
//!
//! Neither one finds secrets in general. A token that is not a known value and not in a URL passes through, so treat
//! them as a second line of defense after keeping secrets out of messages in the first place.
//! [`DomainError::from_error`](crate::DomainError::from_error) applies [`redact_url_userinfo`](crate::redact::redact_url_userinfo) to the text it takes
//! from an error.

/// What a redacted value is replaced with.
pub const REDACTED: &str = "[REDACTED]";

/// Replaces every occurrence of each secret in `text` with [`REDACTED`].
///
/// Empty secrets are ignored. When one secret contains another, the longer one wins, so no part of it is left behind.
/// The text is scanned once, so the marker itself is never searched again and the result is stable if you redact it a
/// second time.
///
/// ```
/// use michi_core::redact::redact_secrets;
///
/// assert_eq!(redact_secrets("auth failed for sk-live-1", &["sk-live-1"]), "auth failed for [REDACTED]");
/// ```
#[must_use]
pub fn redact_secrets(text: &str, secrets: &[&str]) -> String {
    let mut secrets: Vec<&str> = secrets.iter().copied().filter(|s| !s.is_empty()).collect();
    if secrets.is_empty() {
        return text.to_owned();
    }
    secrets.sort_by_key(|s| std::cmp::Reverse(s.len()));
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(c) = rest.chars().next() {
        if let Some(s) = secrets.iter().find(|s| rest.starts_with(**s)) {
            out.push_str(REDACTED);
            rest = &rest[s.len()..];
        } else {
            out.push(c);
            rest = &rest[c.len_utf8()..];
        }
    }
    out
}

/// Replaces the `user:password@` part of every `scheme://…` URL in `text` with [`REDACTED`], keeping the rest.
///
/// A URL runs from its `://` to the next whitespace, quote, backtick, `<` or `>`. Inside it, everything up to the
/// **last** `@` counts as userinfo, so a password that contains `@` or `/` is removed whole. The cost is that a URL
/// with no userinfo but an `@` later in its path (`https://host/pkg@1.2`) loses its host and path up to that `@`;
/// over-redacting is the safe direction here. Bare email addresses are not URLs and are left alone.
///
/// ```
/// use michi_core::redact::redact_url_userinfo;
///
/// assert_eq!(
///     redact_url_userinfo("clone of REDACTED failed"),
///     "clone of https://[REDACTED]@github.com/o/r failed"
/// );
/// ```
#[must_use]
pub fn redact_url_userinfo(text: &str) -> String {
    const SEP: &str = "://";
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(i) = rest.find(SEP) {
        let (head, tail) = rest.split_at(i + SEP.len());
        out.push_str(head);
        let end = tail.find(is_url_end).unwrap_or(tail.len());
        let (url, after) = tail.split_at(end);
        match url.rfind('@') {
            Some(at) => {
                out.push_str(REDACTED);
                out.push_str(&url[at..]);
            }
            None => out.push_str(url),
        }
        rest = after;
    }
    out.push_str(rest);
    out
}

fn is_url_end(c: char) -> bool {
    c.is_whitespace() || matches!(c, '"' | '\'' | '`' | '<' | '>')
}

