#[derive(Debug, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub struct Hint(pub String);

impl Hint {
    pub fn new(s: impl Into<String>) -> Self {
        Self(s.into())
    }

    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl From<&str> for Hint {
    fn from(s: &str) -> Self {
        Self(s.into())
    }
}

impl From<String> for Hint {
    fn from(s: String) -> Self {
        Self(s)
    }
}

impl std::fmt::Display for Hint {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

#[must_use]
pub fn render_hints(hints: &[Hint]) -> String {
    if hints.is_empty() {
        return String::new();
    }
    let mut out = String::with_capacity(12 + hints.len() * 50);
    append_hints(&mut out, hints);
    out
}

pub fn append_hints(out: &mut String, hints: &[Hint]) {
    append_help_block(out, hints.iter().map(Hint::as_str));
}

pub(crate) fn start_block(out: &mut String) {
    if !out.is_empty() && !out.ends_with('\n') {
        out.push('\n');
    }
}

pub(crate) fn append_help_block<'a, I>(out: &mut String, hints: I)
where
    I: ExactSizeIterator<Item = &'a str>,
{
    append_inline_strings(out, "help", hints);
}

pub(crate) fn append_inline_strings<'a, I>(out: &mut String, key: &str, items: I)
where
    I: ExactSizeIterator<Item = &'a str>,
{
    if items.len() == 0 {
        return;
    }
    start_block(out);
    out.push_str(key);
    out.push('[');
    out.push_str(&items.len().to_string());
    out.push_str("]: ");
    for (i, item) in items.enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&crate::toon::escape_value(item));
    }
}

