            if let Some(i) = n.as_i64() {
                Ok(KvValue::Int(i))
            } else if let Some(u) = n.as_u64() {
                match exact_u64_as_f64(u) {
                    Some(f) => Ok(KvValue::Float(f, crate::kv::exact_decimals(f))),
                    None => Err(format!(
